import "server-only";

import { createClient } from "@/server/supabase/server";

export type Severity = "critical" | "major" | "minor";

export type IssueType = {
  code: string;
  label: string;
  severity: Severity;
  active: boolean;
};

/** The whole issue catalog, retired types included (old reviews still show them). */
export async function listIssueTypes(): Promise<IssueType[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("issue_types")
    .select("code, label, severity, active")
    .order("sort_order");
  if (error) throw error;
  return data.map((it) => ({ ...it, severity: it.severity as Severity }));
}

export type SaveReviewInput = {
  replyId: string;
  score: number;
  comment: string;
  issueCodes: string[];
};

/** Why save_review refused, from the SQLSTATE it raised (see its migration). */
export type SaveReviewFailure = "not_found" | "forbidden" | "invalid";

export class SaveReviewError extends Error {
  constructor(
    readonly reason: SaveReviewFailure,
    message: string,
  ) {
    super(message);
    this.name = "SaveReviewError";
  }
}

// The message of a mapped failure reaches the user as is. The migration keeps
// them static; interpolating an id or any row data there would leak it.
const FAILURE_BY_CODE: Record<string, SaveReviewFailure> = {
  PT404: "not_found",
  "42501": "forbidden",
  "22023": "invalid",
};

/**
 * Writes the caller's review and its issues in one transaction. The function
 * derives brand_id from the reply and reviewer_id from the session, so neither
 * travels in the request.
 */
export async function saveReview(input: SaveReviewInput): Promise<string> {
  const supabase = await createClient();
  const { data, error } = await supabase.rpc("save_review", {
    p_reply_id: input.replyId,
    p_score: input.score,
    p_comment: input.comment,
    p_issue_codes: input.issueCodes,
  });
  if (error) {
    const reason = FAILURE_BY_CODE[error.code];
    if (reason) throw new SaveReviewError(reason, error.message);
    throw error;
  }
  return data;
}
import "server-only";

import { createClient } from "@/server/supabase/server";
import type { TimeRange } from "@/server/time";

export type BrandReplySummary = {
  id: string;
  externalId: string;
  subject: string;
  specialist: { id: string; name: string };
  sentAt: string;
  score: number | null;
};

/**
 * Replies of one brand, newest first, as the caller is allowed to see them. The
 * query does not filter by author: RLS returns every reply to a lead of the
 * brand and only their own to a specialist. Message bodies are left out; this
 * is a listing (TASK-003, Q13).
 */
export async function listBrandReplies(brandId: string, viewerId: string): Promise<BrandReplySummary[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("replies")
    .select(
      "id, external_id, subject, sent_at, specialist_id, specialist:profiles!replies_specialist_id_fkey(full_name), reviews(score, reviewer_id, created_at)",
    )
    .eq("brand_id", brandId)
    .order("sent_at", { ascending: false })
    .order("created_at", { referencedTable: "reviews", ascending: false });
  if (error) throw error;

  return data.map((r) => ({
    id: r.id,
    externalId: r.external_id,
    subject: r.subject,
    // The generated type says non-null, but RLS decides whether the embedded
    // profile is visible. A policy gap should show up as a label, not a 500.
    specialist: { id: r.specialist_id, name: r.specialist?.full_name ?? "Former specialist" },
    sentAt: r.sent_at,
    score: scoreFor(r.reviews, viewerId),
  }));
}

/**
 * A reply can have one review per lead. A lead sees their own score; anyone
 * else (the specialist) sees the most recent one. Without this, a second lead
 * on the brand would make the listed score depend on row order.
 */
function scoreFor(reviews: { score: number; reviewer_id: string }[], viewerId: string): number | null {
  const own = reviews.find((rv) => rv.reviewer_id === viewerId);
  return (own ?? reviews[0])?.score ?? null;
}

export type QueueItem = {
  id: string;
  ticketRef: string;
  subject: string;
  brand: { id: string; slug: string; name: string };
  specialistName: string;
  sentAt: string;
  /** The caller's own score, or null while they have not reviewed it. */
  myScore: number | null;
};

/**
 * Replies sent in the range in the given brands, oldest first, with the
 * caller's own score. The caller passes only the brands they lead; RLS would
 * hide the rest anyway, but a person who leads one brand and writes in
 * another must not find their own replies in their queue.
 */
export async function listReviewQueue(
  brandIds: string[],
  viewerId: string,
  range: TimeRange,
): Promise<QueueItem[]> {
  if (brandIds.length === 0) return [];
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("replies")
    .select(
      "id, ticket_ref, subject, sent_at, brand:brands!inner(id, slug, name), specialist:profiles!replies_specialist_id_fkey(full_name), reviews(score, reviewer_id)",
    )
    .in("brand_id", brandIds)
    .gte("sent_at", range.start)
    .lt("sent_at", range.end)
    // Filters the embedded reviews, not the replies: unreviewed replies stay.
    .eq("reviews.reviewer_id", viewerId)
    .order("sent_at")
    .order("id");
  if (error) throw error;

  return data.map((r) => ({
    id: r.id,
    ticketRef: r.ticket_ref,
    subject: r.subject,
    brand: r.brand,
    specialistName: r.specialist?.full_name ?? "Former specialist",
    sentAt: r.sent_at,
    myScore: r.reviews[0]?.score ?? null,
  }));
}

export type ReplyReview = {
  id: string;
  reviewerId: string;
  reviewerName: string;
  score: number;
  comment: string;
  issueCodes: string[];
  updatedAt: string;
};

export type ReplyDetail = {
  id: string;
  ticketRef: string;
  subject: string;
  customerMessage: string;
  replyBody: string;
  receivedAt: string;
  sentAt: string;
  specialist: { id: string; name: string };
  brand: { id: string; slug: string; name: string; keyRule: string; guidelines: string };
  reviews: ReplyReview[];
};

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * One reply with its brand rules and the reviews the caller may see, or null
 * when it does not exist or RLS hides it (a lead of the brand and the author
 * see it; nobody else). A malformed id is also null rather than a Postgres
 * cast error.
 */
export async function getReplyDetail(replyId: string): Promise<ReplyDetail | null> {
  if (!UUID.test(replyId)) return null;
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("replies")
    .select(
      `id, ticket_ref, subject, customer_message, reply_body, received_at, sent_at, specialist_id,
       brand:brands!inner(id, slug, name, key_rule, guidelines),
       specialist:profiles!replies_specialist_id_fkey(full_name),
       reviews(id, reviewer_id, score, comment, updated_at,
               reviewer:profiles!reviews_reviewer_id_fkey(full_name),
               review_issues(issue_code))`,
    )
    .eq("id", replyId)
    .order("updated_at", { referencedTable: "reviews", ascending: false })
    .maybeSingle();
  if (error) throw error;
  if (!data) return null;

  return {
    id: data.id,
    ticketRef: data.ticket_ref,
    subject: data.subject,
    customerMessage: data.customer_message,
    replyBody: data.reply_body,
    receivedAt: data.received_at,
    sentAt: data.sent_at,
    specialist: { id: data.specialist_id, name: data.specialist?.full_name ?? "Former specialist" },
    brand: {
      id: data.brand.id,
      slug: data.brand.slug,
      name: data.brand.name,
      keyRule: data.brand.key_rule,
      guidelines: data.brand.guidelines,
    },
    reviews: data.reviews.map((rv) => ({
      id: rv.id,
      reviewerId: rv.reviewer_id,
      reviewerName: rv.reviewer?.full_name ?? "Former lead",
      score: rv.score,
      comment: rv.comment,
      issueCodes: rv.review_issues.map((ri) => ri.issue_code),
      updatedAt: rv.updated_at,
    })),
  };
}

/**
 * The brand of a reply the caller can see, or null. The review action reads
 * brand_id from here, never from the request.
 */
export async function getReplyBrandId(replyId: string): Promise<string | null> {
  if (!UUID.test(replyId)) return null;
  const supabase = await createClient();
  const { data, error } = await supabase.from("replies").select("brand_id").eq("id", replyId).maybeSingle();
  if (error) throw error;
  return data?.brand_id ?? null;
}
import Link from "next/link";
import { demoPeopleOptions } from "@/features/session/current-person";
import { PersonPicker } from "@/features/session/person-picker";
import { isDemoLoginEnabled } from "@/server/auth/demo-users";
import { getOptionalUser } from "@/server/auth/session";
import { EmptyState } from "@/ui/empty-state";

// Every brand in the seed, including ones the current person cannot see, so the
// API links below show both the 200 and the 403.
const SEED_BRAND_SLUGS = ["voltra", "boxwell", "hebra"];

export default async function HomePage() {
  const user = await getOptionalUser();

  if (!user) {
    if (!isDemoLoginEnabled()) {
      return (
        <EmptyState
          title="Demo sign-in is disabled"
          description="Add DEMO_USER_PASSWORD to apps/web/.env.local (see .env.example) and restart pnpm dev."
        />
      );
    }
    return (
      <section className="flex flex-col gap-6">
        <header className="flex flex-col gap-2">
          <h1 className="font-display text-2xl font-bold tracking-tight">Choose a person</h1>
          <p className="max-w-prose text-sm text-ink-muted">
            Sign-in is simulated; access is not. Each person sees only what their role in each brand allows,
            and the server enforces it.
          </p>
        </header>
        <PersonPicker people={demoPeopleOptions()} />
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-8">
      <header className="flex flex-col gap-2">
        <h1 className="font-display text-2xl font-bold tracking-tight">Hi, {user.fullName.split(" ")[0]}</h1>
        <p className="max-w-prose text-sm text-ink-muted">This is what the server grants you.</p>
        {user.memberships.some((m) => m.role === "lead") ? (
          <Link
            href="/review"
            className="self-start rounded-md bg-accent px-4 py-2 text-sm font-semibold text-accent-ink hover:opacity-90"
          >
            Open yesterday&apos;s review queue
          </Link>
        ) : null}
      </header>

      {user.memberships.length === 0 ? (
        <EmptyState title="No brands yet" description="Ask a lead to add you to a brand." />
      ) : (
        <ul className="divide-y divide-line rounded-lg border border-line bg-surface">
          {user.memberships.map((m) => (
            <li key={m.brandId} className="flex items-center justify-between px-5 py-3">
              <span className="font-medium">{m.name}</span>
              <span className="font-mono text-2xs uppercase tracking-widest text-ink-muted">{m.role}</span>
            </li>
          ))}
        </ul>
      )}

      <div className="flex flex-col gap-2">
        <h2 className="text-sm font-semibold">Check the API</h2>
        <p className="text-sm text-ink-muted">A brand you are not part of answers 403.</p>
        <ul className="flex flex-wrap gap-2">
          {SEED_BRAND_SLUGS.map((slug) => (
            <li key={slug}>
              <a
                href={`/api/brands/${slug}/replies`}
                className="inline-block rounded-md border border-line bg-surface px-3 py-1.5 font-mono text-xs text-accent hover:border-accent"
              >
                /api/brands/{slug}/replies
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
import Link from "next/link";
import type { ReactNode } from "react";
import { currentPersonOption, demoPeopleOptions } from "@/features/session/current-person";
import { UserSwitcher } from "@/features/session/user-switcher";
import { isDemoLoginEnabled } from "@/server/auth/demo-users";
import { getOptionalUser } from "@/server/auth/session";

/** Top-level frame: brand mark on the left, the user switcher on the right. */
export async function AppShell({ children }: { children: ReactNode }) {
  const user = await getOptionalUser();

  return (
    <div className="flex min-h-screen flex-col">
      <header className="sticky top-0 z-10 border-b border-line bg-surface/90 backdrop-blur">
        <div className="mx-auto flex h-14 max-w-6xl items-center justify-between gap-4 px-4 sm:px-6">
          <Link href="/" className="flex shrink-0 items-baseline gap-2">
            <span className="font-display text-base font-bold tracking-tight">Sellervate</span>
            <span className="font-mono text-2xs uppercase tracking-widest text-ink-muted">QA</span>
          </Link>
          <UserSwitcher
            people={demoPeopleOptions()}
            current={currentPersonOption(user)}
            enabled={isDemoLoginEnabled()}
          />
        </div>
      </header>
      <main className="mx-auto w-full max-w-6xl flex-1 px-4 py-8 sm:px-6">{children}</main>
    </div>
  );
}
import type { ReplyReview } from "@/server/data/replies";
import type { IssueType } from "@/server/data/reviews";
import { formatDate } from "@/server/time";
import { ScoreBadge } from "./score-badge";
import { SEVERITY_CHIP, SEVERITY_ORDER } from "./tones";

/** A saved review, read-only: score, issues (critical first) and comment. */
export function ReviewSummary({ review, issueTypes }: { review: ReplyReview; issueTypes: IssueType[] }) {
  const issues = review.issueCodes
    .map((code) => issueTypes.find((it) => it.code === code))
    .filter((it): it is IssueType => it !== undefined)
    .sort((a, b) => SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity));

  return (
    <article className="flex flex-col gap-3 rounded-lg border border-line bg-surface p-4">
      <header className="flex items-center gap-3">
        <ScoreBadge score={review.score} size="lg" />
        <div className="flex min-w-0 flex-col">
          <span className="truncate text-sm font-semibold">{review.reviewerName}</span>
          <span className="font-mono text-2xs text-ink-muted">Reviewed {formatDate(review.updatedAt)}</span>
        </div>
      </header>
      {issues.length > 0 ? (
        <ul className="flex flex-wrap gap-1.5" aria-label="Issues">
          {issues.map((it) => (
            <li key={it.code} className={`max-w-full truncate rounded-full border px-3 py-1 text-xs ${SEVERITY_CHIP[it.severity]}`}>
              {it.label}
            </li>
          ))}
        </ul>
      ) : null}
      {review.comment ? <p className="max-w-prose whitespace-pre-line text-sm">{review.comment}</p> : null}
    </article>
  );
}
import type { Severity } from "@/server/data/reviews";

/**
 * Severity and score are the only things that get semantic colour: critical is
 * bad, major is warn, minor stays neutral (docs/PLAN.md § 9).
 */
export const SEVERITY_ORDER: Severity[] = ["critical", "major", "minor"];

export const SEVERITY_LABEL: Record<Severity, string> = {
  critical: "Critical",
  major: "Major",
  minor: "Minor",
};

export const SEVERITY_TEXT: Record<Severity, string> = {
  critical: "text-bad",
  major: "text-warn",
  minor: "text-ink-muted",
};

/** A read-only issue chip. */
export const SEVERITY_CHIP: Record<Severity, string> = {
  critical: "border-bad/40 bg-bad-soft text-bad",
  major: "border-warn/40 bg-warn-soft text-warn",
  minor: "border-line bg-sunken text-ink-muted",
};

export function scoreTone(score: number): string {
  if (score <= 2) return "border-bad/40 bg-bad-soft text-bad";
  if (score === 3) return "border-warn/40 bg-warn-soft text-warn";
  return "border-good/40 bg-good-soft text-good";
}
